import * as Sentry from "@sentry/nextjs/cloudflare";
import { scrubBreadcrumb, scrubEvent } from "@hilltop/shared/telemetry";
/* eslint-disable @typescript-eslint/ban-ts-comment */
// @ts-ignore `.open-next/worker.js` is generated by `opennextjs-cloudflare build`.
import handler from "./.open-next/worker.js";

/*
 * The deployed Worker: OpenNext's handler wrapped by Sentry, so server errors and
 * request traces are reported. Next.js catches errors while rendering and logs them
 * instead of throwing, so logged errors are reported too, without personal data
 * (see @hilltop/shared/telemetry). (Next's instrumentation hook isn't used: its
 * server chunk isn't bundled for Workers.) `next dev` doesn't use this file.
 *
 * Once a day it also deletes photos that were uploaded but never used on a listing,
 * or that came off one, more than a day ago (see photo_uploads in the database).
 */

type PhotoBucket = { delete(keys: string[]): Promise<void> };
type Env = {
  SENTRY_DSN?: string;
  CF_VERSION_METADATA?: { id: string };
  SUPABASE_URL?: string;
  SUPABASE_SECRET_KEY?: string;
  PHOTOS?: PhotoBucket;
  PUSH_WEBHOOK_SECRET?: string;
};

// The revalidation queue lives in a Durable Object, so queued work survives the Worker restarting.
// @ts-ignore Generated with the worker above.
export { DOQueueHandler } from "./.open-next/worker.js";

async function removeUnusedPhotos(env: Env) {
  if (!env.SUPABASE_URL || !env.SUPABASE_SECRET_KEY || !env.PHOTOS) return;
  const headers = { apikey: env.SUPABASE_SECRET_KEY, "content-type": "application/json", prefer: "return=representation" };
  const cutoff = new Date(Date.now() - 86_400_000).toISOString();
  for (let round = 0; round < 20; round++) {
    const res = await fetch(
      `${env.SUPABASE_URL}/rest/v1/photo_uploads?select=key&attached=eq.false&created_at=lt.${cutoff}&order=created_at&limit=50`,
      { headers },
    );
    if (!res.ok) throw new Error(`Couldn't list unused photos: ${res.status}`);
    const rows = (await res.json()) as { key: string }[];
    if (!rows.length) return;
    // Forget the rows first (only while still unused), then delete exactly those files.
    const list = rows.map((r) => `"${r.key}"`).join(",");
    const gone = await fetch(`${env.SUPABASE_URL}/rest/v1/photo_uploads?key=in.(${list})&attached=eq.false&select=key`, {
      method: "DELETE",
      headers,
    });
    if (!gone.ok) throw new Error(`Couldn't clear unused photos: ${gone.status}`);
    const keys = ((await gone.json()) as { key: string }[]).map((r) => r.key);
    if (keys.length) await env.PHOTOS.delete(keys);
    if (rows.length < 50) return;
  }
}

export default Sentry.withSentry(
  (env: Env) => ({
    dsn: env.SENTRY_DSN,
    release: env.CF_VERSION_METADATA?.id,
    environment: "production",
    tracesSampleRate: 0.1,
    beforeSend: scrubEvent,
    beforeBreadcrumb: scrubBreadcrumb,
    integrations: [Sentry.captureConsoleIntegration({ levels: ["error"] })],
  }),
  {
    fetch: handler.fetch,
    async scheduled(_controller: { cron: string }, env: Env, ctx: { waitUntil(promise: Promise<unknown>): void }) {
      if (_controller.cron === "17 3 * * *") ctx.waitUntil(removeUnusedPhotos(env));
      if (_controller.cron === "* * * * *" && env.PUSH_WEBHOOK_SECRET) {
        ctx.waitUntil(
          handler
            .fetch(
              new Request("https://hilltop.lumavok.com/api/push", {
                method: "POST",
                headers: { "content-type": "application/json", "x-hilltop-webhook": env.PUSH_WEBHOOK_SECRET },
                body: "{}",
              }),
              env,
              ctx,
            )
            .then((response: Response) => {
              if (!response.ok) throw new Error(`Push queue drain failed: ${response.status}`);
            }),
        );
      }
    },
  } as Parameters<typeof Sentry.withSentry<Env>>[1],
);
